BEGIN;
SET LOCAL ROLE service_role;
DO $$
DECLARE actor uuid:=gen_random_uuid();other_owner uuid:=gen_random_uuid();outsider uuid:=gen_random_uuid();domain uuid;d jsonb;w jsonb;a jsonb;b jsonb;pending jsonb;claim jsonb;prior_lease uuid;version uuid;count_before integer;
BEGIN
 INSERT INTO auth.users(id) VALUES(actor),(other_owner),(outsider);INSERT INTO public.user_roles VALUES(actor,'admin'),(other_owner,'admin');
 w:=public.redirect_qr_style_resource(actor);
 IF w->>'logoSource'<>'default' OR w->'effectiveLogo'<>'null'::jsonb THEN RAISE EXCEPTION 'Default logo is not empty';END IF;
 BEGIN PERFORM public.redirect_qr_style_resource(actor,p_values=>'{"version":null,"logoMode":"custom"}');RAISE EXCEPTION 'Custom without upload accepted';EXCEPTION WHEN invalid_parameter_value THEN NULL;END;
 BEGIN PERFORM public.reserve_redirect_qr_logo(outsider,NULL,NULL,'image/png',100,64,64,repeat('a',64));RAISE EXCEPTION 'Non-owner reserved upload';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 BEGIN PERFORM public.reserve_redirect_qr_logo(actor,NULL,NULL,'image/svg+xml',100,64,64,repeat('a',64));RAISE EXCEPTION 'SVG reserved';EXCEPTION WHEN invalid_parameter_value THEN NULL;END;
 a:=public.reserve_redirect_qr_logo(actor,NULL,NULL,'image/png',100,64,64,repeat('a',64));
 IF a->>'key'<>(a->>'id')||'.png' THEN RAISE EXCEPTION 'Unsafe upload key';END IF;
 w:=public.finish_redirect_qr_logo(actor,(a->>'id')::uuid);
 IF w->>'logoMode'<>'custom' OR w->>'logoSource'<>'workspace' OR w#>>'{effectiveLogo,id}'<>a->>'id' THEN RAISE EXCEPTION 'Workspace upload not attached';END IF;
 IF (w->'effectiveLogo')-ARRAY['id','key','mime','bytes','width','height','sha256']::text[]<>'{}' THEN RAISE EXCEPTION 'Private asset fields leaked';END IF;
 d:=public.redirect_domain_resource('create',actor,p_values=>'{"hostname":"qr-logo.example.com"}');domain:=(d->>'id')::uuid;
 d:=public.redirect_qr_style_resource(actor,domain);
 IF d->>'logoSource'<>'workspace' OR d#>>'{effectiveLogo,id}'<>a->>'id' THEN RAISE EXCEPTION 'Domain did not inherit workspace logo';END IF;
 d:=public.redirect_qr_style_resource(actor,domain,'{"version":null,"logoMode":"none"}');
 IF d->>'logoSource'<>'hidden' OR d->'effectiveLogo'<>'null'::jsonb THEN RAISE EXCEPTION 'Domain hide bypassed';END IF;
 b:=public.reserve_redirect_qr_logo(actor,domain,(d->>'version')::uuid,'image/jpeg',100,64,64,repeat('b',64));
 BEGIN PERFORM public.finish_redirect_qr_logo(other_owner,(b->>'id')::uuid);RAISE EXCEPTION 'Different owner consumed reservation';EXCEPTION WHEN invalid_parameter_value THEN NULL;END;
 d:=public.finish_redirect_qr_logo(actor,(b->>'id')::uuid);
 IF d->>'logoSource'<>'domain' OR d#>>'{effectiveLogo,id}'<>b->>'id' THEN RAISE EXCEPTION 'Domain override missing';END IF;
 d:=public.redirect_qr_style_resource(actor,domain,jsonb_build_object('version',d->>'version','logoMode','inherit'));
 IF d#>>'{effectiveLogo,id}'<>a->>'id' OR d#>>'{logoAsset,id}'<>b->>'id' THEN RAISE EXCEPTION 'Inherit lost retained custom upload';END IF;
 UPDATE public.redirect_qr_assets SET next_cleanup_at=now()-interval '1 second' WHERE id=(b->>'id')::uuid;
 IF public.claim_redirect_qr_asset_cleanup()<>'[]'::jsonb THEN RAISE EXCEPTION 'Retained logo was deleted';END IF;
 d:=public.redirect_qr_style_resource(actor,domain,jsonb_build_object('version',d->>'version','logoMode','custom'));
 pending:=public.reserve_redirect_qr_logo(actor,NULL,(w->>'version')::uuid,'image/png',100,64,64,repeat('c',64));
 DELETE FROM public.user_roles WHERE user_id=actor;
 BEGIN PERFORM public.finish_redirect_qr_logo(actor,(pending->>'id')::uuid);RAISE EXCEPTION 'Revoked actor finished upload';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 INSERT INTO public.user_roles VALUES(actor,'admin');
 w:=public.redirect_qr_style_resource(actor,p_values=>jsonb_build_object('version',w->>'version','clearLogo',true));
 BEGIN PERFORM public.finish_redirect_qr_logo(actor,(pending->>'id')::uuid);RAISE EXCEPTION 'Stale upload overwrote newer preference';EXCEPTION WHEN unique_violation THEN NULL;END;
 UPDATE public.redirect_qr_assets SET next_cleanup_at=now()-interval '1 second' WHERE id=(a->>'id')::uuid;
 claim:=public.claim_redirect_qr_asset_cleanup(1)->0;
 IF claim->>'id'<>a->>'id' OR public.finish_redirect_qr_asset_cleanup((a->>'id')::uuid,gen_random_uuid(),true) THEN RAISE EXCEPTION 'Wrong cleanup lease accepted';END IF;
 IF NOT public.finish_redirect_qr_asset_cleanup((a->>'id')::uuid,(claim->>'lease')::uuid,true) THEN RAISE EXCEPTION 'Cleanup acknowledgement lost';END IF;
 BEGIN PERFORM public.finish_redirect_qr_logo(actor,(a->>'id')::uuid);RAISE EXCEPTION 'Deleted asset reattached';EXCEPTION WHEN invalid_parameter_value THEN NULL;END;
 UPDATE public.redirect_qr_assets SET expires_at=now()-interval '1 second',next_cleanup_at=now()-interval '1 second' WHERE id=(pending->>'id')::uuid;
 BEGIN PERFORM public.finish_redirect_qr_logo(actor,(pending->>'id')::uuid);RAISE EXCEPTION 'Expired upload activated';EXCEPTION WHEN invalid_parameter_value THEN NULL;END;
 claim:=public.claim_redirect_qr_asset_cleanup(1)->0;prior_lease:=(claim->>'lease')::uuid;
 PERFORM public.finish_redirect_qr_asset_cleanup((pending->>'id')::uuid,prior_lease,false);
 IF public.claim_redirect_qr_asset_cleanup()<>'[]'::jsonb THEN RAISE EXCEPTION 'Cleanup retry ignored backoff';END IF;
 UPDATE public.redirect_qr_assets SET next_cleanup_at=now()-interval '1 second' WHERE id=(pending->>'id')::uuid;
 claim:=public.claim_redirect_qr_asset_cleanup(1)->0;
 IF public.finish_redirect_qr_asset_cleanup((pending->>'id')::uuid,prior_lease,true) THEN RAISE EXCEPTION 'Stale acknowledgement consumed retry';END IF;
 PERFORM public.finish_redirect_qr_asset_cleanup((pending->>'id')::uuid,(claim->>'lease')::uuid,true);
 UPDATE public.redirect_qr_assets SET next_cleanup_at=now()-interval '1 second' WHERE id=(a->>'id')::uuid;
 claim:=public.claim_redirect_qr_asset_cleanup(1)->0;
 IF claim->>'id'<>a->>'id' THEN RAISE EXCEPTION 'Tombstone not rechecked for late uploads';END IF;
 PERFORM public.finish_redirect_qr_asset_cleanup((a->>'id')::uuid,(claim->>'lease')::uuid,true);
 pending:=public.reserve_redirect_qr_logo(actor,domain,(d->>'version')::uuid,'image/png',100,64,64,repeat('d',64));
 DELETE FROM public.redirect_domains WHERE id=domain;
 BEGIN PERFORM public.finish_redirect_qr_logo(actor,(pending->>'id')::uuid);RAISE EXCEPTION 'Deleted domain upload attached to workspace';EXCEPTION WHEN no_data_found THEN NULL;END;
 IF NOT EXISTS(SELECT FROM public.redirect_qr_assets WHERE id=(b->>'id')::uuid AND domain_id IS NULL) THEN RAISE EXCEPTION 'Domain deletion lost cleanup metadata';END IF;
 version:=(w->>'version')::uuid;
 FOR count_before IN 1..3 LOOP PERFORM public.reserve_redirect_qr_logo(actor,NULL,version,'image/png',100,64,64,repeat('e',64));END LOOP;
 IF (public.reserve_redirect_qr_logo(actor,NULL,version,'image/png',100,64,64,repeat('e',64))->>'retryAfter')::integer<>900 THEN RAISE EXCEPTION 'Pending upload budget not enforced';END IF;
 IF has_table_privilege('authenticated','public.redirect_qr_assets','SELECT') OR has_function_privilege('anon','public.claim_redirect_qr_asset_cleanup(integer)','EXECUTE') THEN RAISE EXCEPTION 'Private asset lifecycle exposed';END IF;
END $$;
ROLLBACK;
